        lfs->free.end = lfs->free.peak;
        lfs->free.end += lfs->cfg->block_size;
        lfs->free.peak = lfs->free.end;
        lfs->free.peak += lfs->cfg->block_size;
        lfs->free.end %= lfs->cfg->block_size;
        if (lfs->free.i != lfs->block_count-1) {
            lfs->free.i += lfs->cfg->block_size;
        } else {
            lfs->free.i = 0;
        }
    }
    return LFS_ERR_NOSPC;

